package net.minecraft.world;import net.minecraft.world.item.ItemStack;public class SimpleContainer implements Container{private final ItemStack[] items;public SimpleContainer(int n){items=new ItemStack[n];java.util.Arrays.fill(items,ItemStack.EMPTY);}public int getContainerSize(){return items.length;}public ItemStack getItem(int i){return items[i];}public void setItem(int i,ItemStack s){items[i]=s;setChanged();}public ItemStack removeItem(int i,int amount){return items[i].split(amount);}public ItemStack removeItemNoUpdate(int i){ItemStack s=items[i];items[i]=ItemStack.EMPTY;return s;}public boolean isEmpty(){return java.util.Arrays.stream(items).allMatch(ItemStack::isEmpty);}public void clearContent(){java.util.Arrays.fill(items,ItemStack.EMPTY);}public void setChanged(){}}
